  ('feature.practice-engine', 'practice-engine', 'Academic Practice Engine', 'Saves every answer, the student dashboard, Review My Mistakes and goals. Without it, work in this organization isn’t saved.', 'feature', null, null, null, array[]::text[], array[]::text[], array[]::text[], null, null, 'all', 'available', 0),
